import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a (a PENDING claim is never bound: its due is live); `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
  /** The claim's external reference, unique on the sheet regardless of case; "" for none. */
  ref: string;
  /** The claim's tags, lower-cased, sorted and comma separated ("a,b"); "" for none. */
  tags?: string;
  /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
  roundingDate: string;
  /** The claim's due-by, fixed when it was created: its date plus the first of its person's own terms, their grade's terms and the sheet's terms in force on that date. */
  dueBy: string;
  /** The claim's status log, oldest first: "<STATUS> by <user> on <date> due=<due>" per status it has had. */
  log: string[];
  /** The date the claim was last deferred until, "" if it was never deferred. */
  deferredUntil: string;
  /** The claim's proofs count. */
  proofs: string;
  /** The number of the claim a split made this claim from, "" for any other claim. */
  splitFrom: string;
  /** The user whose open editor locks the claim for everyone else, "" when unlocked. */
  lockedBy?: string;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry?: boolean;
  /** The last day (the sheet's today then) a reminder was written for the claim, "" if never. */
  remindedOn?: string;
  /** The reason the claim was voided with, from the sheet's list; "" for none. */
  voidReason?: string;
  /** The claim's comments, oldest first: "<user> on <date>: <text>" each, the date the sheet's today when it was written. */
  comments?: string[];
  /** The claim's lines, oldest first: "<label> <qty> x <unit>" each; with lines, its amount is their amounts added up. */
  lines?: string[];
  /** The number of the bulk settle batch that settled the claim, "" when it was settled one at a time or never. */
  batch?: string;
};

/** OPEN and PENDING claims are open: their due is live (unless bound), they go overdue and a hold
 *  takes them out of the totals. */
export const isOpen = (c: { status?: string }) => c.status === 'OPEN' || c.status === 'PENDING';

/** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';

/** Whether a statement binds the claim's figure now: a PENDING claim is never bound. */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a later date. A deferred claim
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
/** Whether the row shows the claim as deferred: it was deferred until a date after the sheet's today, whatever its
 *  status now (a deferred claim later voided still shows it). Only an OPEN one is held back from the totals (`isDeferred`). */
export const deferredShown = (c: { deferredUntil?: string }, today: string | undefined) =>
  !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

export const isDeferred = (c: { status?: string; deferredUntil?: string }, today: string | undefined) =>
  c.status === 'OPEN' && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not
 *  open, unbound and dated within one of its person's holds (`heldOn`). */
export const countsLive = (c: Claim, heldOn: (date: string) => boolean, today: string | undefined) =>
  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));

/** The status a claim had at the end of the day, as its status log records it (each line dated the sheet's today
 *  when the change was made); undefined when it was added after that day. */
export function statusAt(c: Claim, end: string): ClaimStatus | undefined {
  let at: ClaimStatus | undefined;
  for (const line of c.log ?? []) {
    const m = / on (\d{4}-\d{2}-\d{2}) due=[^ ]*$/.exec(line);
    if (m && m[1] <= end) at = line.slice(0, line.indexOf(' ')) as ClaimStatus;
  }
  return at;
}

/** Whether a claim counts in a period ending on `end`: by the status it had at the end of that day, and, as in the
 *  live totals, not deferred on the sheet's today and not open, unbound and dated within one of its person's holds. */
export const countsAtEnd = (c: Claim, end: string, heldOn: (date: string) => boolean, today: string | undefined) => {
  const then = statusAt(c, end);
  return then !== undefined && counts({ ...c, status: then }) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));
};

export const claimsKey = (sheet: string, asOf = '') => ['sheet', sheet, 'claims', asOf] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: claimsKey(sheet, asOf),
    queryFn: () => getJson<Claim[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    enabled: sheet !== '',
  });
  return data ?? [];
}

export const settleBatchKey = (sheet: string, asOf = '') => ['sheet', sheet, 'settle-batch', asOf] as const;

/** The number of the sheet's last bulk settle batch, "" when there has been none. */
export function useLastSettleBatch(sheet: string): string {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: settleBatchKey(sheet, asOf),
    queryFn: () => getJson<{ last: string }>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/settle-batch`, asOf)),
    enabled: sheet !== '',
  });
  return data?.last ?? '';
}

/** The amounts of the claims that count added up, leaving out corrections (claims that correct another),
 *  shown with two decimals. Summed in whole cents so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter((c) => counts(c) && !c.corrects).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A claim's tags as shown: sorted, comma and space separated. */
export const tagList = (tags: string | undefined) => (tags ?? '').split(',').filter((t) => t !== '').join(', ');

/** Whether a claim carries the tag. */
export const hasTag = (c: { tags?: string }, tag: string) => (c.tags ?? '').split(',').includes(tag);

export const tagsKey = (sheet: string) => ['sheet', sheet, 'tags'] as const;

/** Every tag ever used on the sheet's claims, sorted. */
export function useTags(sheet: string): string[] {
  const { data } = useQuery({
    queryKey: tagsKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/tags`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
import { isDeferred, isOpen, type Claim } from './useClaims';
import type { Grace } from './useGrace';

/** A claim's due-by: fixed when it was created, from the terms of its person's grade in force on its date. */
export const dueBy = (c: Claim) => c.dueBy;

/** The date a claim's lateness counts from: its due-by plus its grace days (see useGrace). */
export function lateFrom(c: { dueBy?: string; personId?: string; date: string }, grace?: Grace): string {
  const days = grace === undefined ? 0 : grace(c);
  if (!c.dueBy || days === 0) return c.dueBy ?? '';
  const d = new Date(`${c.dueBy}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** A claim is overdue when it is OPEN (or PENDING), not deferred, and its due-by plus its grace days is before the sheet's today. */
export const isOverdue = (c: Claim, today: string | undefined, grace?: Grace) =>
  isOpen(c) && !isDeferred(c, today) && today !== undefined && lateFrom(c, grace) < today;
import { gradeOn, usePeople } from '../people/usePeople';
import { inForce, useSettings } from '../settings/useSettings';

/** A claim's grace days: those of its person's grade in force on its date, as in force on that date (0 for none). */
export type Grace = (claim: { personId?: string; date: string }) => number;

export function useGrace(sheet: string): Grace {
  const settings = useSettings(sheet);
  const people = usePeople(sheet);
  const byId = new Map(people.map((p) => [p.id, p]));
  return (claim) => {
    const person = claim.personId === undefined ? undefined : byId.get(claim.personId);
    if (person === undefined) return 0;
    const days = inForce(settings, `grace-${gradeOn(person, claim.date)}`, claim.date, '');
    return days === '' ? 0 : Number.parseInt(days, 10);
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person has any hold and `holds` lists each (from, to; to "" when open-ended): their
 *  OPEN claims dated within one, unless bound by a statement, count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: HoldFrom[];
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
  /** The person's own terms in days; "" for none. */
  terms: string;
  /** The person's contact, trimmed and lower-cased; "" for none. */
  contact: string;
  /** The person's tags, lower-cased, sorted and comma separated ("a,b"); "" for none. */
  tags: string;
  /** The person's aliases, sorted as names are compared. */
  aliases: string[];
  /** Whether the person's name or an alias is used by someone else on a sheet of the sheet's tree. */
  clashing: boolean;
  /** The sheet the person was transferred from; "" for anyone else. */
  origin: string;
  /** The person's past retirements, each "<from> to <the day unretired>", in the order they ended: no claim of
   *  theirs may be dated after the from and before the to of one. */
  retirements: string[];
  /** The person's SNAPSHOT lines, each "<the day being left> <due-total>" ("n/a" for none), oldest first. */
  snapshots: string[];
};

/** A hold from a date to a date, both included (YYYY-MM-DD; to "" when open-ended). */
export type HoldFrom = { from: string; to: string };

/** Whether one of the person's holds covers the date. */
/** Whether the person's retirement date is reached on the sheet's today: from then their OPEN and
 *  PENDING claims, unless bound by a statement, count in no live total. */
export const retiredOn = (person: Person, today: string | undefined) =>
  person.retiredFrom !== '' && today !== undefined && today >= person.retiredFrom;

export const heldOn = (person: Person, date: string) =>
  person.holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
export type GradeFrom = { from: string; grade: string };

/** The person's grade in force on a date: the one with the latest from-date on or before it (with
 *  no date yet, the one in force on the sheet's today as loaded). */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from <= date && (found === undefined || g.from >= found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string, asOf = '') => ['sheet', sheet, 'people', asOf] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheet: string): Person[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: peopleKey(sheet, asOf),
    queryFn: () => getJson<Person[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, asOf)),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** A quotient of integers rounded half to even. */
function divHalfEven(n: bigint, d: bigint): bigint {
  const negative = n < 0n !== d < 0n;
  const a = n < 0n ? -n : n;
  const b = d < 0n ? -d : d;
  const whole = a / b;
  const twice = (a % b) * 2n;
  const rounded = twice > b || (twice === b && whole % 2n === 1n) ? whole + 1n : whole;
  return negative ? -rounded : rounded;
}

/** The person's patrons with their shares in hundredths ("33.33" -> 3333n), in the order named:
 *  100.00 split equally, each share rounded half to even to two decimals, the remainder to the
 *  first-named. */
export function patronShares(person: Person): { id: string; share: bigint }[] {
  const n = BigInt(person.patronIds.length);
  if (n === 0n) return [];
  const each = divHalfEven(10000n, n);
  return person.patronIds.map((id, i) => ({ id, share: i === 0 ? 10000n - each * (n - 1n) : each }));
}

/** A sum of cents times shares in hundredths of a percent (cents * 10000ths), back to cents, half to even. */
export const sharedCents = (cents: bigint) => divHalfEven(cents, 10000n);
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time) through a date ("" for no end). One inherited from an ancestor
 *  sheet has its level: 1 the parent, 2 the parent's parent, 3 the one above; the sheet's own have none. */
export type Rate = { grade: string; rate: string; from: string; to: string; level?: number };

